const problems = [];
for (const { json: r } of $input.all()) {
  let why = null;
  if (r.redirectLoop) why = 'redirect loop';
  else if (!r.ok) why = r.error || `HTTP ${r.finalStatusCode ?? r.statusCode}`;
  else if (r.noindex) why = 'noindex';
  else if (r.robotsTxtAllowsGooglebot === false) why = 'blocked for Googlebot in robots.txt';
  else if (r.canonicalIsSelf === false) why = `canonical points to ${r.canonicalUrl}`;
  if (why) problems.push(`• ${r.url} → ${why}`);
}
if (!problems.length) return [];
return [{ json: { text: `:rotating_light: ${problems.length} key page(s) need attention\n${problems.join('\n')}` } }];
